# 财年 Y 年报对外发布日(近似): (Y+1)-05-01
def available_year_asof(date_str):
    """给定回测日(date_str='YYYY-MM-DD'), 返回当时已发布的**最新**财年 Y。EX-ANTE 边界。"""
    y, m, d = int(date_str[:4]), int(date_str[5:7]), int(date_str[8:10])
    if (m, d) >= (5, 1):
        return y - 1
    return y - 2

def get_fund(code, asof_year):
    """返回 (roe, revg) 或 (None,None)。asof_year 为已发布最新财年。"""
    if asof_year not in DATA:
        # 往前找最近有数据的年(处理上市前缺失)
        for y in range(asof_year, 2013, -1):
            if y in DATA:
                asof_year = y
                break
        else:
            return None, None
    idx = CODES.index(code) if code in CODES else -1
    if idx < 0:
        return None, None
    roe = DATA[asof_year]["roe"][idx]
    revg = DATA[asof_year]["revg"][idx]
    return roe, revg
